const articleData = await browserjs(tabId, () => {
  const h1 = document.querySelector("h1")?.innerText;
  const subhead = document.querySelector(".sub-header, [data-render='sub-headline']")?.innerText;
  const author = document.querySelector(".byline, [data-render='author-name']")?.innerText;
  const paragraphs = Array.from(document.querySelectorAll("article p, .article__body p, #article-body p"))
    .map(p => p.innerText.trim())
    .filter(t => t.length > 0);

  // If no article p found, try general p
  const fallback = paragraphs.length === 0 
    ? Array.from(document.querySelectorAll("p")).map(p => p.innerText.trim()).filter(t => t.length > 0)
    : [];

  return {
    h1,
    subhead,
    author,
    paragraphs: paragraphs.length ? paragraphs : fallback
  };
});

console.log("Article headline:", articleData.h1);
console.log("Paragraphs count:", articleData.paragraphs.length);
console.log("First 10 paragraphs:\n", articleData.paragraphs.slice(0, 10).join("\n\n"));

